/* Pin each paragraph to a corner and add a colored border */

#upleft {
  position: fixed;
  top: 0;
  left: 0;
  margin: 0;
  border: 2px solid red;
}

#upright {
  position: fixed;
  top: 0;
  right: 0;
  margin: 0;
  border: 2px solid green;
}

#downleft {
  position: fixed;
  bottom: 0;
  left: 0;
  margin: 0;
  border: 2px solid orange;
}

#downright {
  position: fixed;
  bottom: 0;
  right: 0;
  margin: 0;
  border: 2px solid blue;
}
